export const datasetSpecs=[
 {id:'telemetry',title:'Rover telemetry with imperfect data',filename:'rover-telemetry.csv',summary:'120 synthetic rows: elapsed time, temperature, voltage, and a status flag. Includes blank readings and explicit stale statuses.',tasks:['Count valid and missing temperatures separately.','Plot only valid temperature observations with labeled axes.','Report the lowest voltage and its timestamp.','Compare results before and after excluding stale samples.'],schema:'time_s: elapsed seconds; temperature_c: degrees Celsius or blank; voltage_v: volts; status: OK or STALE. Entirely invented data.'},
 {id:'cooling',title:'Enclosure cooling experiment',filename:'enclosure-cooling.csv',summary:'61 invented measurements with small deterministic disturbances around a first-order cooling curve.',tasks:['Plot measurement and prediction on the same axes.','Compute measured minus predicted residuals.','Compare two candidate time constants.','Explain why this synthetic fit is not experimental validation.'],schema:'time_s: elapsed seconds; measured_c: synthetic temperature; model_c: 20 + 20 exp(−t/30). No random sampling claims.'},
 {id:'timing',title:'Loop timing under variable load',filename:'loop-timing.csv',summary:'100 simulated execution durations with occasional overruns against a 20 ms interval.',tasks:['Find maximum observed duration and count overruns.','Treat exactly 20 ms separately from greater than 20 ms.','Plot duration against iteration.','Explain why finite observations cannot prove a worst-case bound.'],schema:'iteration: sample index; duration_ms: invented elapsed time; interval_ms: target interval. Not hardware benchmark data.'},
 {id:'components',title:'Instrument mass and power table',filename:'instrument-budget.csv',summary:'A small invented component table suitable for aggregation, validation, and CSV parsing in all five languages.',tasks:['Compute total mass and active power.','Calculate energy at the supplied operating hours.','Keep W and Wh distinct.','Add one malformed row and write an explicit error policy.'],schema:'component: label; mass_kg: kg; power_w: W; operating_hours: h. All values are instructional.'}
];
export function dataset(id){
 if(id==='telemetry')return 'time_s,temperature_c,voltage_v,status\n'+Array.from({length:120},(_,i)=>`${i},${i%19===0?'':(21+0.04*i+Math.sin(i/8)*2).toFixed(2)},${(12.6-i*0.005).toFixed(3)},${i%23===0?'STALE':'OK'}`).join('\n')+'\n';
 if(id==='cooling')return 'time_s,measured_c,model_c\n'+Array.from({length:61},(_,i)=>{const t=i*2,m=20+20*Math.exp(-t/30);return `${t},${(m+0.25*Math.sin(i*1.7)).toFixed(3)},${m.toFixed(3)}`;}).join('\n')+'\n';
 if(id==='timing')return 'iteration,duration_ms,interval_ms\n'+Array.from({length:100},(_,i)=>`${i+1},${i%17===0?24:i%13===0?20:8+i%9},20`).join('\n')+'\n';
 if(id==='components')return 'component,mass_kg,power_w,operating_hours\ncamera,0.25,3,2\ncomputer,0.40,12,3\nsensor,0.05,0.5,4\nradio,0.12,5,1\n';
 throw Error('Unknown dataset');
}
export const mentorPrompt=`Act as a programming tutor for my aerospace studies. Give hints before a solution.\n\nLanguage and concept:\nMy goal:\nMy current code:\nExact error or unexpected result:\nMy expected result and reasoning:\nWhat I have already tried:\n\nHelp me identify the first misunderstanding. Ask me to predict a small case. Explain units, assumptions, and edge cases. After we fix it, give me a different small problem to solve unaided.`;
export function readmeTemplate(title='Engineering learning project'){return `# ${title}\n\n## Question\nWhat question does this project answer?\n\n## Scope and limitations\nEducational work, not validated operational software. State what this does and does not establish.\n\n## Inputs and units\nDocument data origin, schema, units, coordinate conventions, and missing-value policy.\n\n## Assumptions\nList physical and computational assumptions.\n\n## Reproduce\nRecord language/tool versions, setup steps, sample input, and exact run command.\n\n## Verification\nInclude a hand calculation, boundary case, malformed input, and expected output.\n\n## Results\nInclude one clearly labeled plot/table and explain what it supports.\n\n## Uncertainty and failures\nExplain numerical error, measurement limits, and observed failures.\n\n## Next experiment\nName one useful extension and its acceptance criterion.\n`;}
